/Y H:i')); ?></td><td><?php echo e($t->product->name); ?></td><td><?php echo e($t->type==='in'?'Masuk':'Keluar'); ?></td><td><?php echo e($t->quantity); ?></td><td><?php echo e($t->user->name); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="6">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div></div><style>@media print{.sidebar,.topbar,form,button{display:none!important}.main{margin:0;padding:0}.panel{box-shadow:none;border:1px solid #ddd;margin-bottom:10px}}</style><?php $__env->stopSection(); ?>

